H=Path(__file__).resolve().parent;P=H.parents[2];S=H.parent/'screen';AP=H.parent/'action_policy_fast';PC=H.parent/'private_card_fast';PL=H.parent/'private_card_likelihood';sys.path.insert(0,str(AP));import cpu_generate as A
K=['pair_id','direction','hand_id','action_no'];FAMS=['directed_transfer','soft_play','coordinated_isolation']
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def kh(x,cols):return hashlib.sha256(x.select(cols).sort(cols).write_csv().encode()).hexdigest()
def score(d,p,n):
 y=d['action_class'].to_numpy();i=np.arange(d.height);g=np.log(np.maximum(p[i,y],1e-12))-np.log(np.maximum(n[i,y],1e-12));z=d.select('pair_id','direction').with_columns(pl.Series('g',g)).group_by('pair_id','direction').agg(pl.mean('g')).group_by('pair_id').agg(pl.mean('g').alias('v'),pl.col('direction').n_unique().alias('nd'));assert z['nd'].min()==2;return z.drop('nd')
def pipeline(d,cap,inputs,trtabs,hetabs,nuisance,prior,normal_path,o,j,deadline):
 tr=d.filter(pl.col('table_id').is_in(trtabs)).join(cap,on=K,how='semi').with_columns(pl.Series('_sub',[A.bit(t,o,j,'sub') for t in d.filter(pl.col('table_id').is_in(trtabs)).join(cap,on=K,how='semi')['table_id']])).with_row_index('_i');he=d.filter(pl.col('table_id').is_in(hetabs));assert not(set(tr['table_id'])&set(he['table_id'])) and not(set(tr['actor_id'])&set(he['actor_id'])) and not(set(tr['hand_id'])&set(he['hand_id']));pred=np.empty(tr.height)
 assert kh(tr,K)==prior['train_keys'] and kh(he,K)==prior['held_keys']
 for col in ['table_id','actor_id','hand_id']:assert kh(tr.unique(col),[col])==prior['train_'+col.removesuffix('_id')+'s'] and kh(he.unique(col),[col])==prior['held_'+col.removesuffix('_id')+'s']
 for s in [0,1]:
  q=tr.filter(pl.col('_sub')==s);ft=tr.filter(pl.col('_sub')!=s);old=prior['sub'][s];assert kh(ft,K)==old['train_keys'] and kh(q,K)==old['score_keys']
  for col in ['table_id','actor_id','hand_id']:assert kh(ft.unique(col),[col])==old['train_'+col.removesuffix('_id')+'s'] and kh(q.unique(col),[col])==old['score_'+col.removesuffix('_id')+'s']
  pred[q['_i'].to_numpy()]=nuisance['strength_sub'][s].predict(q.select(inputs).to_numpy())
 tr=tr.with_columns(pl.Series('private_surprise',tr['partner_strength'].to_numpy()-pred));he=he.with_columns(pl.Series('private_surprise',he['partner_strength'].to_numpy()-nuisance['strength_full'].predict(he.select(inputs).to_numpy())));Xh=he.select(inputs+['private_surprise']).to_numpy();normal_bundle=joblib.load(normal_path);normal=normal_bundle['normal'];pn=normal.predict_proba(Xh);assert np.array_equal(normal.classes_,np.arange(4)) and pn.shape==(he.height,4) and np.isfinite(pn).all() and (pn>=0).all() and (pn<=1).all() and np.allclose(pn.sum(1),1,atol=1e-6)
 nz,nw=A.weights(tr.filter(pl.col('label')==0));savedm=pl.read_parquet(AP/f'train_membership_outer{o}_pipeline{j}_normal.parquet').sort(K);now=nz.select(*K,'table_id','actor_id').with_columns(pl.Series('fit_weight',nw)).sort(K);assert savedm.columns==now.columns and savedm.equals(now)
 savedp=pl.read_parquet(AP/f'action_predictions_outer{o}_pipeline{j}.parquet').select(*K,*[f'normal_p{k}' for k in range(4)]);chk=he.select(K).with_row_index('_i').join(savedp,on=K,validate='1:1',maintain_order='left');assert np.array_equal(pn,np.column_stack([chk[f'normal_p{k}'] for k in range(4)]));vals=[];mods={};receipts=[];allp={'normal':pn}
 for fam in FAMS:
  z,w=A.weights(tr.filter((pl.col('label')==1)&(pl.col('behavior_family')==fam)));assert z.height and set(z['action_class'])=={0,1,2,3} and time.monotonic()<deadline;m=A.model().fit(z.select(inputs+['private_surprise']).to_numpy(),z['action_class'].to_numpy(),sample_weight=w);assert np.array_equal(m.classes_,np.arange(4));q=m.predict_proba(Xh);assert q.shape==(he.height,4) and np.isfinite(q).all() and (q>=0).all() and (q<=1).all() and np.allclose(q.sum(1),1,atol=1e-6);vals.append(score(he,q,pn).rename({'v':fam}));mods[fam]=m;allp[fam]=q;mp=H/f'membership_outer{o}_pipeline{j}_{fam}.parquet';assert not mp.exists();z.select(*K,'table_id','actor_id').with_columns(pl.Series('weight',w)).write_parquet(mp);receipts.append({'family':fam,'rows':z.height,'membership_sha256':sha(mp)})
 rp=H/f'family_models_outer{o}_pipeline{j}.joblib';assert not rp.exists();joblib.dump(mods,rp)
 for fam in FAMS:assert np.array_equal(joblib.load(rp)[fam].predict_proba(Xh),allp[fam])
 pp=H/f'family_action_probabilities_outer{o}_pipeline{j}.parquet';assert not pp.exists();pf=he.select(*K,'table_id','action_class');
 for name,q in allp.items():pf=pf.with_columns(*[pl.Series(f'{name}_p{k}',q[:,k]) for k in range(4)])
 pf.write_parquet(pp);out=vals[0].join(vals[1],on='pair_id',validate='1:1').join(vals[2],on='pair_id',validate='1:1');receipts.append({'model_sha256':sha(rp),'probabilities_sha256':sha(pp),'reload_all3_exact':True,'normal_membership_and_probabilities_exact':True});return out,mods,receipts
def main():
 st=time.monotonic();dl=st+900;man=H/'MANIFEST.json';rel=H/'CPU_RELEASE.json';assert rel.exists() and json.loads(rel.read_text())['manifest_sha256']==sha(man);mm=json.loads(man.read_text());assert all(sha(Path(k))==v for k,v in mm['sources'].items()) and not(H/'CPU_RECEIPT.json').exists() and not any(H.glob('fast131_context_fold*.npz')) and not any(H.glob('family_models_outer*.joblib')) and not any(H.glob('family_action_probabilities*.parquet')) and not any(H.glob('membership_outer*.parquet'));old=json.loads((PC/'CPU_RECEIPT.json').read_text());lm=json.loads((PL/'MANIFEST.json').read_text());inputs=lm['inputs'];paths=[P/k for k in lm['sources'] if k.startswith('reports/conditional-action-experiment/action-cache/')];d=pl.read_parquet(paths).join(pl.read_parquet(PL/'row_membership.parquet').select(*K,'actor_id'),on=K,validate='1:1').join(pl.read_csv(P/'data/development_labels.csv').select('pair_id','label','behavior_family'),on='pair_id',validate='m:1');cap=pl.read_parquet(PL/'capped_training_keys.parquet').select(K);tabs=sorted(d['table_id'].unique().to_list());fm={t:A.fold(t) for t in tabs};raw=pl.read_parquet(P/'Claude Version/experiments/crossphase_20260911/lab_on_dev.parquet').with_columns(pl.Series('_f',[A.fold(t) for t in pl.read_parquet(P/'Claude Version/experiments/crossphase_20260911/lab_on_dev.parquet')['table_id']]));rec=[]
 for o in [0,1]:
  nuis=joblib.load(PC/f'cpu_models_outer{o}.joblib');outer=[t for t in tabs if fm[t]!=o];held=[t for t in tabs if fm[t]==o];pieces=[];models=[];fits=[]
  for j in [0,1]:
   he=[t for t in outer if A.bit(t,o,0,'inner')==j];tr=[t for t in outer if t not in he];q,m,r=pipeline(d,cap,inputs,tr,he,nuis[j],old['folds'][o]['pipelines'][j],AP/f'policy_models_outer{o}_pipeline{j}.joblib',o,j,dl);pieces.append(q);models.append(m);fits+=r
  train=pl.concat(pieces);test,m,r=pipeline(d,cap,inputs,outer,held,nuis[2],old['folds'][o]['pipelines'][2],AP/f'policy_models_outer{o}_pipeline2.joblib',o,2,dl);models.append(m);fits+=r;ctx=np.load(S/f'context_fold{o}.npz',allow_pickle=False);trids=raw.filter(pl.col('_f')!=o)['pair_id'].to_list();heids=raw.filter(pl.col('_f')==o)['pair_id'].to_list();tm={r[0]:r[1:] for r in train.iter_rows()};hm={r[0]:r[1:] for r in test.iter_rows()};tv=np.array([tm[x] for x in trids],np.float32);hv=np.array([hm[x] for x in heids],np.float32);assert np.array_equal(np.asarray(heids),ctx['pair_id']);dest=H/f'fast131_context_fold{o}.npz';np.savez_compressed(dest,X_train=np.c_[ctx['X_train'],tv],y_train=ctx['y_train'],X_held=np.c_[ctx['X_held'],hv],pair_id=ctx['pair_id'],feature_name=np.concatenate([ctx['feature_name'],np.array(['llr_dt','llr_sp','llr_ci'])]));ck=np.load(dest,allow_pickle=False);assert np.array_equal(ck['X_train'][:,:128],ctx['X_train'],equal_nan=True) and np.array_equal(ck['X_held'][:,:128],ctx['X_held'],equal_nan=True) and np.array_equal(ck['feature_name'][:128],ctx['feature_name']);mp=H/f'family_models_outer{o}.joblib';joblib.dump(models,mp);rec.append({'fold':o,'context_sha256':sha(dest),'models_sha256':sha(mp),'fits':fits,'first128_exact':True})
 assert time.monotonic()<dl;(H/'CPU_RECEIPT.json').write_text(json.dumps({'manifest_sha256':sha(man),'new_family_fits':18,'reused_normal_fits':6,'seconds':time.monotonic()-st,'folds':rec},indent=2)+'\n')
